contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner, address thirdParty) public {
        require(newOwner != address(0));
        require(thirdParty != address(0));
        require(thirdParty != address(this));

        // Initial owner is address(this); newOwner is distinct and non-zero.
        c.transferOwnership(newOwner);

        // The old owner (this contract) should now be unable to transfer ownership again.
        bool oldOwnerReverted;
        try c.transferOwnership(thirdParty) { oldOwnerReverted = false; } catch { oldOwnerReverted = true; }
        address ownerAfterOldOwnerAttempt = c.owner();

        // The new owner (newOwner) should be able to transfer ownership to thirdParty.
        // We simulate newOwner by having this contract call transferOwnership only if it is the owner,
        // but since it is not, we instead verify the revert behavior and state consistency.
        // To check that newOwner can transfer, we use the fact that onlyOwner checks msg.sender == owner.
        // Our contract cannot impersonate newOwner, so we assert that the old owner's failed attempt
        // did not change the owner and that the owner is still newOwner.
        assert(oldOwnerReverted && ownerAfterOldOwnerAttempt == newOwner);
    }
}

